{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C02","C01","C06","C12","C14","C03","C08","C05","C09","C16","C13"],
  "contradictory_card_ids": ["C50","C54","C63","C65","C68","C73"],
  "prediction_basis_card_ids": ["C02","C01","C03","C06","C12","C14"],
  "claims": [
    {
      "claim": "The closest direct oral-bioavailability context, a fused lactam bearing a sulfonamide-linked basic piperazine, showed 34% F in fasted healthy volunteers derived from IV and oral profiles, above the 20% threshold.",
      "card_ids": ["C02"]
    },
    {
      "claim": "Other lactam contexts are also at or above threshold: ziprasidone 30% fasted and about 60% fed, and praziquantel 27.2% even in cirrhotic patients.",
      "card_ids": ["C01","C06","C12","C14","C03"]
    },
    {
      "claim": "L6 M01 (fasudil) shares the isoquinoline sulfonyl homopiperazine core but is the isoquinoline, not the query's isoquinolin-1-one; its high intrinsic clearance and AO-mediated metabolism are not directly transferable to the 1-oxo query without query-specific data.",
      "card_ids": ["C63","C65","C68","C73"]
    },
    {
      "claim": "L6 M02/M03 records are mixed (moderate S9 clearance for ripasudil, low microsomal clearance for the benzamide), so the hepatic-clearance family does not provide coherent affirmative low-F evidence for the query.",
      "card_ids": ["C62","C64","C67","C69","C70","C71","C72","C66"]
    },
    {
      "claim": "Efflux liabilities in L5 (vardenafil, CPI-169) are mechanistic only and do not establish low F; the same family includes efflux substrates with adequate oral exposure.",
      "card_ids": ["C50","C54","C59","C53","C61"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C62","C63","C64","C65","C66","C67","C68","C69","C70","C71","C72","C73"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule.",
    "No query-specific hepatic clearance or metabolic-stability assay is supplied; L6 records are for fasudil, ripasudil, and a benzamide analog.",
    "The query's permeability and absorption are not directly measured; low logD and low neutral fraction raise uncertainty but are not affirmative evidence of F below 20%.",
    "Formulation, dose, and prandial-state effects for the query are unmeasured."
  ],
  "decision_summary": "Prediction remains high. L6 hepatic-clearance records show high intrinsic clearance for fasudil, a close isoquinoline sulfonyl homopiperazine analog, but the query is the isoquinolin-1-one form, so the AO-mediated high-clearance pathway is not directly transferable; M02/M03 records are mixed. The closest direct F context C02 reports 34% in humans, above threshold, and other lactam contexts are also >=27%. Confidence stays moderate."
}

